-- ATTENTION: This table is included in an airflow definition. Any table or
-- column name change must be reflected there.
CREATE TABLE `ts_deliveries` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  `repository_id` bigint unsigned NOT NULL,
  `repository_nwo` varchar(140) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `ref` varbinary(1024) NOT NULL,
  `commit_oid` varchar(40) COLLATE utf8mb4_general_ci NOT NULL,
  `environment` json NOT NULL,
  `checkout_uri` varchar(1024) COLLATE utf8mb4_general_ci NOT NULL,
  `analysis_key` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `source_repository_id` bigint unsigned NOT NULL,
  `complete` tinyint(1) NOT NULL DEFAULT '1',
  `failed` tinyint(1) NOT NULL DEFAULT '0',
  `build_started_at` datetime(6) DEFAULT NULL,
  `workflow_run_id` bigint unsigned DEFAULT NULL,
  `workflow_run_attempt` bigint unsigned DEFAULT NULL,
  `upload_started_at` datetime(6) DEFAULT NULL,
  `upload_finished_at` datetime(6) DEFAULT NULL,
  `hydro_enqueued_at` datetime(6) DEFAULT NULL,
  `processing_lock` varchar(36) DEFAULT NULL,
  `processing_started_at` datetime(6) DEFAULT NULL,
  `processing_completed_at` datetime(6) DEFAULT NULL,
  `sarif_path` text COLLATE utf8mb4_general_ci NOT NULL,
  `sarif_id` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `origin` tinyint unsigned NOT NULL,
  `workflow_path` varbinary(1024) DEFAULT NULL,
  -- Category values are truncated to 1000 char but this field is defined with a larger capacity. See https://github.com/github/code-scanning/issues/12629
  `outdated_config_category` varchar(1024) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `outdated_config_tool_name` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `check_run_ids` json DEFAULT NULL,
  `request_id` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `analysis_name` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `track_status` tinyint(1) DEFAULT NULL,
  `owner_id` bigint unsigned DEFAULT NULL,
  `audit_log_context` json DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_deliveries_on_repo_id_sarif_id` (`repository_id`,`sarif_id`),
  KEY `idx_deliveries_on_repo_id_ref_key` (`repository_id`, `ref`, `analysis_key`),
  KEY `idx_deliveries_on_repo_id_complete` (`repository_id`, `complete`),
  KEY `idx_deliveries_on_repo_id_workflow_run_id` (`repository_id`, `workflow_run_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
